sp_widget.css:
/* ==========================================
   CAMPUS FOOD SERVICES ASSISTANT
   Enhanced Simple Animated Styling
   ========================================== */

* {
  box-sizing: border-box;
}

/* ==========================================
   HERO
   ========================================== */

.cfa-hero {
  position: relative;
  overflow: hidden;
  background: linear-gradient(
    135deg,
    #0d9488,
    #0f766e 45%,
    #0f172a
  );
  background-size: 200% 200%;
  color: #fff;
  padding: 90px 24px;
  text-align: center;
  animation: cfa-gradient 10s ease infinite;
}

.cfa-hero::before,
.cfa-hero::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}

.cfa-hero::before {
  width: 280px;
  height: 280px;
  top: -120px;
  left: -80px;
  background: rgba(255,255,255,.07);
  animation: cfa-float 7s ease-in-out infinite;
}

.cfa-hero::after {
  width: 350px;
  height: 350px;
  right: -150px;
  bottom: -180px;
  background: rgba(255,255,255,.05);
  animation: cfa-float 9s ease-in-out infinite reverse;
}

.cfa-hero-inner {
  position: relative;
  z-index: 2;
  max-width: 720px;
  margin: 0 auto;
  animation: cfa-fade-up .8s ease both;
}

.cfa-hero h1 {
  font-size: 34px;
  margin-bottom: 16px;
  font-weight: 800;
  letter-spacing: -.5px;
}

.cfa-hero p {
  font-size: 15px;
  opacity: .92;
  margin-bottom: 28px;
  line-height: 1.7;
}

.cfa-hero-btn {
  background: #fff;
  color: #0f766e;
  padding: 13px 28px;
  border-radius: 9px;
  font-weight: 700;
  text-decoration: none;
  font-size: 14px;
  display: inline-block;
  transition:
    transform .25s ease,
    box-shadow .25s ease,
    background .25s ease;
}

.cfa-hero-btn:hover {
  background: #f0fdfa;
  transform: translateY(-3px);
  box-shadow: 0 10px 25px rgba(0,0,0,.18);
  text-decoration: none;
}

.cfa-hero-btn:active {
  transform: translateY(-1px);
}


/* ==========================================
   WELCOME
   ========================================== */

.cfa-welcome {
  padding: 60px 24px;
  background: #fff;
}

.cfa-welcome-inner {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.cfa-welcome-inner h2 {
  font-size: 23px;
  margin-bottom: 12px;
  color: #0f172a;
}

.cfa-welcome-inner > p {
  font-size: 14px;
  color: #64748b;
  line-height: 1.7;
  margin-bottom: 34px;
}

.cfa-welcome-points {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 20px;
  text-align: left;
}

.cfa-welcome-point {
  display: flex;
  gap: 13px;
  align-items: flex-start;
  padding: 17px;
  border-radius: 12px;
  transition:
    transform .25s ease,
    background .25s ease,
    box-shadow .25s ease;
}

.cfa-welcome-point:hover {
  background: #f8fafc;
  transform: translateY(-4px);
  box-shadow: 0 8px 20px rgba(15,23,42,.06);
}

.cfa-wp-icon {
  font-size: 22px;
  flex-shrink: 0;
  transition: transform .3s ease;
}

.cfa-welcome-point:hover .cfa-wp-icon {
  transform: scale(1.15) rotate(-5deg);
}

.cfa-welcome-point b {
  display: block;
  font-size: 13.5px;
  color: #0f172a;
  margin-bottom: 3px;
}

.cfa-welcome-point span {
  font-size: 12px;
  color: #64748b;
  line-height: 1.5;
}


/* ==========================================
   SERVICES
   ========================================== */

.cfa-services {
  max-width: 1100px;
  margin: 0 auto;
  padding: 65px 24px;
}

.cfa-services h2 {
  text-align: center;
  font-size: 24px;
  margin-bottom: 36px;
  color: #0f172a;
}

.cfa-services-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 18px;
}

.cfa-service-card {
  position: relative;
  overflow: hidden;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 21px;
  transition:
    transform .28s ease,
    box-shadow .28s ease,
    border-color .28s ease;
}

.cfa-service-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: linear-gradient(90deg,#0d9488,#0f766e);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .3s ease;
}

.cfa-service-card:hover {
  transform: translateY(-6px);
  border-color: #99f6e4;
  box-shadow: 0 12px 28px rgba(15,23,42,.09);
}

.cfa-service-card:hover::before {
  transform: scaleX(1);
}

.cfa-service-icon {
  font-size: 27px;
  margin-bottom: 9px;
  display: inline-block;
  transition:
    transform .3s ease;
}

.cfa-service-card:hover .cfa-service-icon {
  transform: scale(1.15) translateY(-2px);
}

.cfa-service-card h4 {
  font-size: 14.5px;
  margin-bottom: 7px;
  color: #0f172a;
}

.cfa-service-card p {
  font-size: 12.5px;
  color: #64748b;
  line-height: 1.55;
  margin: 0;
}


/* ==========================================
   ABOUT
   ========================================== */

.cfa-about {
  background: #f1f5f9;
  padding: 65px 24px;
}

.cfa-about-inner {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.cfa-about h2 {
  font-size: 24px;
  margin-bottom: 16px;
  color: #0f172a;
}

.cfa-about p {
  font-size: 14px;
  color: #475569;
  line-height: 1.7;
  margin-bottom: 28px;
}

.cfa-team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 14px;
  margin-bottom: 20px;
}

.cfa-team-card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 17px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  transition:
    transform .25s ease,
    box-shadow .25s ease;
}

.cfa-team-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 20px rgba(15,23,42,.08);
}

.cfa-team-card b {
  font-size: 13.5px;
  color: #0f172a;
}

.cfa-team-card span {
  font-size: 11.5px;
  color: #64748b;
}

.cfa-college {
  font-size: 12.5px;
  color: #94a3b8;
  font-weight: 600;
}


/* ==========================================
   CONTACT
   ========================================== */

.cfa-contact {
  padding: 65px 24px;
  background: #fff;
}

.cfa-contact-inner {
  max-width: 900px;
  margin: 0 auto;
  text-align: center;
}

.cfa-contact h2 {
  font-size: 24px;
  margin-bottom: 28px;
  color: #0f172a;
}

.cfa-contact-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.cfa-contact-card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 23px;
  transition:
    transform .25s ease,
    box-shadow .25s ease,
    border-color .25s ease;
}

.cfa-contact-card:hover {
  transform: translateY(-5px);
  border-color: #99f6e4;
  box-shadow: 0 10px 25px rgba(15,23,42,.08);
}

.cfa-contact-icon {
  font-size: 27px;
  margin-bottom: 9px;
  display: inline-block;
  transition: transform .3s ease;
}

.cfa-contact-card:hover .cfa-contact-icon {
  transform: scale(1.12);
}

.cfa-contact-card b {
  display: block;
  font-size: 14px;
  margin-bottom: 5px;
  color: #0f172a;
}

.cfa-contact-card span {
  font-size: 12.5px;
  color: #64748b;
}


/* ==========================================
   FOOTER
   ========================================== */

.cfa-footer {
  background: #0f172a;
  color: #94a3b8;
  text-align: center;
  padding: 21px 24px;
  font-size: 12px;
}

.cfa-footer p {
  margin: 0;
}


/* ==========================================
   ANIMATIONS
   ========================================== */

@keyframes cfa-fade-up {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes cfa-gradient {
  0% {
    background-position: 0% 50%;
  }

  50% {
    background-position: 100% 50%;
  }

  100% {
    background-position: 0% 50%;
  }
}

@keyframes cfa-float {
  0%,
  100% {
    transform: translateY(0) scale(1);
  }

  50% {
    transform: translateY(-18px) scale(1.04);
  }
}


/* ==========================================
   RESPONSIVE
   ========================================== */

@media (max-width: 600px) {

  .cfa-hero {
    padding: 70px 20px;
  }

  .cfa-hero h1 {
    font-size: 28px;
  }

  .cfa-hero p {
    font-size: 14px;
  }

  .cfa-services,
  .cfa-about,
  .cfa-contact {
    padding: 50px 20px;
  }

  .cfa-services-grid {
    grid-template-columns: 1fr;
  }

  .cfa-team-grid {
    grid-template-columns: 1fr 1fr;
  }

}


/* ==========================================
   ACCESSIBILITY
   ========================================== */

@media (prefers-reduced-motion: reduce) {

  .cfa-hero,
  .cfa-hero::before,
  .cfa-hero::after,
  .cfa-hero-inner {
    animation: none;
  }

  .cfa-service-card,
  .cfa-team-card,
  .cfa-contact-card,
  .cfa-welcome-point,
  .cfa-hero-btn {
    transition: none;
  }

}

sp_widget.script:
(function() {

    // Native Service Portal login URL
    data.loginUrl = '/sp?id=food_service_login_page';

    // Current year for footer
    data.year = new GlideDateTime().getYearLocalTime();

})();
